from functools import cache

calls = 0

@cache
def fib(n):
    global calls
    calls += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(30), calls)

import sys
sys.setrecursionlimit(200)

def depth(n):
    return depth(n + 1) if n < 5000 else n

try:
    print(depth(0))
except RecursionError:
    print("too deep")

def collect(n, acc=[]):
    if n == 0:
        return acc
    acc.append(n)
    return collect(n - 1, acc)

print(collect(3), collect(2))

def go(n):
    if n == 0:
        return ""
    return str(n) + go(n - 1) + str(n)

print(go(3))

from functools import cache

@cache
def total_sum(nums):
    return sum(nums)

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
